package dk.stream.android;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import okhttp3.*;
import org.json.JSONObject;

/** Records the encoded TV source directly; the foreground service owns and finalizes the file. */
@androidx.media3.common.util.UnstableApi
public final class TvRecordingService extends Service {
 private static final int ID=2020;private static volatile boolean active;private static volatile String channel;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
 private final OkHttpClient http=new OkHttpClient.Builder().connectTimeout(20,TimeUnit.SECONDS).readTimeout(30,TimeUnit.SECONDS).build();
 private volatile boolean stop;private volatile Call call;private PowerManager.WakeLock wake;private long bytes;private boolean hasMedia,started;
 static boolean active(){return active;}
 static void start(Context context,Playlist.Channel source){if(active)return;active=true;channel=source.name;try{androidx.core.content.ContextCompat.startForegroundService(context,new Intent(context,TvRecordingService.class).putExtra("url",source.url).putExtra("name",source.name));}catch(RuntimeException error){active=false;throw error;}}
 static void stop(Context context){context.startService(new Intent(context,TvRecordingService.class).setAction("stop"));}
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("tv_recording",UiText.text("TV-optagelse"),NotificationManager.IMPORTANCE_LOW));wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Stream:recording");wake.acquire(12*60*60*1000L);}
 private Notification notice(){PendingIntent open=PendingIntent.getActivity(this,ID,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent finish=PendingIntent.getService(this,ID,new Intent(this,TvRecordingService.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"tv_recording"):new Notification.Builder(this);return builder.setSmallIcon(R.drawable.brand_icon).setContentTitle(UiText.text(stop?"Gemmer optagelse …":"Optagelse i gang")).setContentText(channel).setOngoing(true).setOnlyAlertOnce(true).setContentIntent(open).addAction(R.drawable.ic_stop,"Stop optagelse",finish).build();}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null){stopSelf();return START_NOT_STICKY;}if("stop".equals(intent.getAction())){stop=true;Call current=call;if(current!=null)current.cancel();if(active)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,notice());else stopSelf();return START_NOT_STICKY;}if(started)return START_NOT_STICKY;String url=intent.getStringExtra("url");if(url==null){stopSelf();return START_NOT_STICKY;}channel=intent.getStringExtra("name");started=true;active=true;startForeground(ID,notice());worker.execute(()->record(url));return START_NOT_STICKY;}
 private Response get(String url)throws IOException {Call next=http.newCall(new Request.Builder().url(Playlist.httpUrl(url)).build());call=next;if(stop){next.cancel();throw new IOException("Stopped");}Response response=next.execute();if(!response.isSuccessful()||response.body()==null){response.close();throw new IOException("TV-kilden svarede ikke ("+response.code()+").");}return response;}
 private byte[] data(String url)throws IOException{try(Response response=get(url)){if(response.body().contentLength()>64L*1024*1024)throw new IOException("TV-segmentet er for stort.");try(InputStream input=response.body().byteStream();ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[32768];int count;while((count=input.read(buffer))!=-1){if(output.size()+count>64*1024*1024)throw new IOException("TV-segmentet er for stort.");output.write(buffer,0,count);}return output.toByteArray();}}}
 private void record(String url){Uri destination=null;OutputStream output=null;Response upstream=null;String failure=null;try{
  Response first=get(url);upstream=first;String address=first.request().url().toString();BufferedInputStream input=new BufferedInputStream(first.body().byteStream());input.mark(512);byte[] peek=new byte[8];int length=0;while(length<peek.length){int count=input.read(peek,length,peek.length-length);if(count<0)break;length+=count;}input.reset();boolean hls=length>=7&&new String(peek,0,length,java.nio.charset.StandardCharsets.UTF_8).startsWith("#EXTM3U");
  if(hls){String text;try{byte[] playlist=readLimited(input,2*1024*1024);text=new String(playlist,java.nio.charset.StandardCharsets.UTF_8);}finally{first.close();}TvRecordingPlaylist snapshot=TvRecordingPlaylist.parse(address,text);for(int depth=0;snapshot.variant!=null;depth++){if(depth>=4)throw new IOException("Ugyldig TV-afspilningsliste.");try(Response response=get(snapshot.variant)){address=response.request().url().toString();snapshot=TvRecordingPlaylist.parse(address,new String(readLimited(response.body().byteStream(),2*1024*1024),java.nio.charset.StandardCharsets.UTF_8));}}
   if(snapshot.segments.isEmpty())throw new IOException("TV-kilden har ingen optagelige segmenter.");
   boolean fragmented=snapshot.segments.get(snapshot.segments.size()-1).init!=null;destination=create(fragmented?"mp4":"ts");output=getContentResolver().openOutputStream(destination,"wt");if(output==null)throw new IOException("Download-mappen kan ikke åbnes.");long next=Math.max(snapshot.segments.get(0).sequence,snapshot.segments.get(snapshot.segments.size()-1).sequence-1);String init=null;Map<String,byte[]> keys=new HashMap<>();
   while(!stop){for(TvRecordingPlaylist.Segment segment:snapshot.segments){if(stop)break;if(segment.sequence<next)continue;if(segment.init!=null&&!segment.init.equals(init)){if(init!=null)throw new IOException("TV-kilden ændrede videoformat under optagelsen.");byte[] header=data(segment.init);output.write(header);bytes+=header.length;init=segment.init;}
     byte[] part=data(segment.url);if(segment.key!=null){byte[] key=keys.get(segment.key);if(key==null){key=data(segment.key);keys.put(segment.key,key);}javax.crypto.Cipher cipher=javax.crypto.Cipher.getInstance("AES/CBC/PKCS5Padding");byte[] iv=TvRecordingPlaylist.iv(segment.iv,segment.sequence);cipher.init(javax.crypto.Cipher.DECRYPT_MODE,new javax.crypto.spec.SecretKeySpec(key,"AES"),new javax.crypto.spec.IvParameterSpec(iv));part=cipher.doFinal(part);}
     if(!fragmented&&(part.length<188||part[0]!=0x47))throw new IOException("TV-kildens optagelsesformat understøttes ikke.");output.write(part);bytes+=part.length;hasMedia=true;next=segment.sequence+1;
    }if(snapshot.ended||stop)break;for(long wait=0;wait<Math.min(5000,snapshot.targetSeconds*500)&&!stop;wait+=100)Thread.sleep(100);if(stop)break;try(Response response=get(address)){snapshot=TvRecordingPlaylist.parse(response.request().url().toString(),new String(readLimited(response.body().byteStream(),2*1024*1024),java.nio.charset.StandardCharsets.UTF_8));}}
  }else{if(length==0||peek[0]!=0x47){first.close();throw new IOException("Optagelse kræver en TV-kilde med HLS eller MPEG-TS.");}destination=create("ts");output=getContentResolver().openOutputStream(destination,"wt");if(output==null){first.close();throw new IOException("Download-mappen kan ikke åbnes.");}try(Response ignored=first){byte[] buffer=new byte[32768];int count;while(!stop&&(count=input.read(buffer))!=-1){output.write(buffer,0,count);bytes+=count;hasMedia=true;}}}
 }catch(Exception error){if(!stop)failure=error.getMessage()==null?"TV-kilden kunne ikke optages.":error.getMessage();}finally{if(upstream!=null)upstream.close();if(output!=null)try{output.close();}catch(IOException error){failure="Optagelsen kunne ikke gemmes.";}if(destination!=null){if(hasMedia)try{DownloadDestination.publish(this,destination);}catch(IOException error){failure="Optagelsen kunne ikke gemmes.";DownloadDestination.remove(this,destination);}else DownloadDestination.remove(this,destination);}String message=failure!=null?"Optagelse stoppet: "+failure:hasMedia?"Optagelsen er gemt i Download.":"Ingen optagelse blev gemt.";main.post(()->{UiText.toast(this,message,android.widget.Toast.LENGTH_LONG).show();stopForeground(true);stopSelf();});}}
 private static byte[] readLimited(InputStream input,int limit)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){if(bytes.size()+count>limit)throw new IOException("TV-afspilningslisten er for stor.");bytes.write(buffer,0,count);}return bytes.toByteArray();}
 private Uri create(String extension)throws Exception{return DownloadDestination.create(this,new JSONObject().put("name",channel+" - "+new java.text.SimpleDateFormat("yyyy-MM-dd HH-mm-ss",Locale.ROOT).format(new Date())+"."+extension).put("mime",extension.equals("ts")?"video/mp2t":"video/mp4"));}
 @Override public void onDestroy(){active=false;stop=true;Call current=call;if(current!=null)current.cancel();worker.shutdown();if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
